//#region src/psql/describe/versionGate.ts
/**
* Encode major[.minor] into the server_version_num integer form.
* For PG >= 10 the minor component is ignored (single-component versioning).
*
* `major` may also be an already-encoded `ServerVersion` (>= 10000), in which
* case it is returned unchanged — this lets callers pass either the bare
* major number (e.g. `11`) or one of the `PG_*` constants (e.g. `PG_11`).
*/
const encode = (major, minor = 0) => {
	if (major >= 1e4) return major;
	if (major >= 10) return major * 1e4;
	return major * 1e4 + minor * 100;
};
const serverAtLeast = (actual, major, minor = 0) => actual >= encode(major, minor);
const serverLess = (actual, major, minor = 0) => actual < encode(major, minor);
const PG_9_0 = 9e4;
const PG_9_1 = 90100;
const PG_9_2 = 90200;
const PG_9_3 = 90300;
const PG_9_4 = 90400;
const PG_9_5 = 90500;
const PG_9_6 = 90600;
const PG_10 = 1e5;
const PG_11 = 11e4;
const PG_12 = 12e4;
const PG_13 = 13e4;
const PG_14 = 14e4;
const PG_15 = 15e4;
const PG_16 = 16e4;
const PG_17 = 17e4;
const PG_18 = 18e4;
const PG_19 = 19e4;
//#endregion
export { PG_10, PG_11, PG_12, PG_13, PG_14, PG_15, PG_16, PG_17, PG_18, PG_19, PG_9_0, PG_9_1, PG_9_2, PG_9_3, PG_9_4, PG_9_5, PG_9_6, serverAtLeast, serverLess };
